<?php
/* 3G's Narrator (Oct 31 2026). One narration engine for everything: decks, landing pages, ads, walkthroughs.
   Admin: GET ?a=status|list|get&p=..     POST {a:save|make|remake|delete}
   Public: GET ?a=show&p=<id>   -> the manifest a player needs
           GET ?a=play&p=<id>&i=<n>  -> the mp3 (cached, shareable, no password)
   Data: tt_data/narration/<hash>.mp3, tt_data/narrations.json
   The voice runs on the same engine as the Voices panel and shares its monthly cap. */
declare(strict_types=1);
require_once __DIR__ . '/svc_lib.php';
@set_time_limit(300);

const NR_VOICES = ['onyx' => 'Onyx - deep, authoritative man', 'ash' => 'Ash - warm, steady man', 'echo' => 'Echo - clear, friendly man',
  'verse' => 'Verse - smooth, expressive man', 'ballad' => 'Ballad - gentle, storyteller', 'sage' => 'Sage - calm, wise woman',
  'coral' => 'Coral - warm, welcoming woman', 'nova' => 'Nova - bright, energetic woman', 'shimmer' => 'Shimmer - soft, polished woman',
  'alloy' => 'Alloy - neutral, balanced', 'fable' => 'Fable - expressive, British tone'];
const NR_MODELS = ['gpt-4o-mini-tts' => 'Studio (you can direct the tone)', 'tts-1-hd' => 'High quality', 'tts-1' => 'Fast'];
const NR_TONES = [
  'authority' => 'Speak like a confident, successful Black business owner addressing a room of peers. Warm but certain. Unhurried. Land every full stop.',
  'teacher'   => 'Speak like a patient teacher walking one person through something for the first time. Clear, friendly, never rushed.',
  'preacher'  => 'Speak with warmth and conviction, like a trusted leader speaking to his congregation. Build gently, never shout.',
  'news'      => 'Speak like a steady news presenter. Even pace, clean diction, no selling.',
  'hype'      => 'Speak with energy and momentum, like a trailer. Punchy, short beats, confident.',
  'calm'      => 'Speak slowly and calmly, like a documentary narrator. Low and reassuring.',
];

function nr_json($x, int $c = 200) { http_response_code($c); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); echo json_encode($x, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE); exit; }
function nr_dir() { $d = TTS_DATA . '/narration'; if (!is_dir($d)) @mkdir($d, 0750, true); return $d; }
function nr_all() { $d = tt_read('narrations.json'); return (array)($d['projects'] ?? []); }
function nr_get($p) { $p = preg_replace('/[^a-z0-9-]/', '', strtolower((string)$p)); $a = nr_all(); return $a[$p] ?? null; }
function nr_key() { $k = (string)tt_c('TT_OPENAI_KEY', ''); if ($k === '') { $s = tt_read('ai_settings.json'); if (is_array($s)) $k = (string)($s['key'] ?? ''); } return trim($k); }
function nr_hash($text, $voice, $model, $speed) { return substr(hash('sha256', $voice . '|' . $model . '|' . $speed . '|' . $text), 0, 40); }
function nr_use_get() { $f = nr_dir() . '/usage.json'; $u = json_decode(is_file($f) ? (string)file_get_contents($f) : '{}', true); if (!is_array($u)) $u = []; $m = date('Y-m'); return [$f, $u, $m, (int)($u[$m] ?? 0)]; }
function nr_use_add(int $n) { [$f, $u, $m, $c] = nr_use_get(); $u[$m] = $c + $n; @file_put_contents($f, json_encode($u), LOCK_EX); }
function nr_cap() { return (int)tt_c('TT_VOICE_CAP', '60000'); }

// one line of narration -> a cached mp3. Returns [hash, error]
function nr_speak($text, $voice, $model, $speed, $tone) {
  $text = trim($text);
  if ($text === '') return ['', 'empty'];
  if (mb_strlen($text) > 3800) return ['', 'A single line must be under 3800 characters.'];
  $h = nr_hash($text, $voice, $model, $speed);
  $f = nr_dir() . '/' . $h . '.mp3';
  if (is_file($f) && filesize($f) > 500) return [$h, ''];
  $key = nr_key();
  if ($key === '') return ['', 'The voice engine is not switched on for this server yet.'];
  [, , , $used] = nr_use_get();
  if ($used + mb_strlen($text) > nr_cap()) return ['', 'Monthly voice limit reached (' . $used . ' of ' . nr_cap() . ' characters). It resets next month.'];
  $body = ['model' => $model, 'voice' => $voice, 'input' => $text, 'response_format' => 'mp3', 'speed' => $speed];
  if ($model === 'gpt-4o-mini-tts' && $tone !== '') $body['instructions'] = mb_substr($tone, 0, 400);
  $ch = curl_init('https://api.openai.com/v1/audio/speech');
  curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 120, CURLOPT_POST => true,
    CURLOPT_POSTFIELDS => json_encode($body), CURLOPT_HTTPHEADER => ['Authorization: Bearer ' . $key, 'Content-Type: application/json']]);
  $r = (string)curl_exec($ch); $c = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
  if ($c !== 200 || strlen($r) < 500) {
    $j = json_decode($r, true); $msg = is_array($j) ? (string)($j['error']['message'] ?? '') : '';
    return ['', $msg !== '' ? 'Voice engine said: ' . mb_substr($msg, 0, 160) : 'The voice engine did not answer. Try again.'];
  }
  if (@file_put_contents($f, $r, LOCK_EX) === false) return ['', 'Could not save the audio. Storage is not writable.'];
  nr_use_add(mb_strlen($text));
  return [$h, ''];
}

$a = (string)($_GET['a'] ?? '');
$m = $_SERVER['REQUEST_METHOD'] ?? 'GET';

/* ---------- public: anyone with the link can play it ---------- */
if ($a === 'play' && $m === 'GET') {
  $P = nr_get($_GET['p'] ?? ''); $i = (int)($_GET['i'] ?? -1);
  if (!$P || empty($P['live'])) { http_response_code(404); exit; }
  $it = $P['items'][$i] ?? null;
  $h = $it ? (string)($it['hash'] ?? '') : '';
  $f = preg_match('/^[a-f0-9]{40}$/', $h) ? nr_dir() . '/' . $h . '.mp3' : '';
  if (!$f || !is_file($f)) { http_response_code(404); exit; }
  header('Content-Type: audio/mpeg');
  header('Cache-Control: public, max-age=604800, immutable');
  header('Content-Length: ' . filesize($f));
  header('Accept-Ranges: none');
  readfile($f); exit;
}
if ($a === 'show' && $m === 'GET') {
  $P = nr_get($_GET['p'] ?? '');
  if (!$P || empty($P['live'])) nr_json(['error' => 'Not found.'], 404);
  $items = [];
  foreach (($P['items'] ?? []) as $i => $it) {
    $items[] = ['k' => (string)($it['k'] ?? ('s' . $i)), 'title' => (string)($it['title'] ?? ''),
      'text' => (string)($it['text'] ?? ''), 'img' => (string)($it['img'] ?? ''),
      'audio' => !empty($it['hash']) ? 'api/narrator.php?a=play&p=' . rawurlencode($P['id']) . '&i=' . $i : ''];
  }
  nr_json(['ok' => true, 'id' => $P['id'], 'title' => (string)($P['title'] ?? ''), 'sub' => (string)($P['sub'] ?? ''),
    'voice' => (string)($P['voice'] ?? ''), 'items' => $items]);
}

/* ---------- desk ---------- */
tt_require_admin();
if ($m === 'GET') {
  [, , , $used] = nr_use_get();
  if ($a === 'status') nr_json(['ok' => true, 'ready' => nr_key() !== '', 'voices' => NR_VOICES, 'models' => NR_MODELS, 'tones' => NR_TONES, 'used' => $used, 'cap' => nr_cap()]);
  if ($a === 'get') { $P = nr_get($_GET['p'] ?? ''); if (!$P) nr_json(['error' => 'Not found.'], 404); nr_json(['ok' => true, 'project' => $P]); }
  $list = [];
  foreach (nr_all() as $P) {
    $done = 0; foreach (($P['items'] ?? []) as $it) if (!empty($it['hash'])) $done++;
    $list[] = ['id' => $P['id'], 'title' => $P['title'] ?? '', 'items' => count($P['items'] ?? []), 'done' => $done,
      'voice' => $P['voice'] ?? '', 'live' => !empty($P['live']), 'updated' => (int)($P['updated'] ?? 0),
      'url' => tt_site() . '/narrate/?p=' . rawurlencode((string)$P['id'])];
  }
  usort($list, function ($x, $y) { return $y['updated'] <=> $x['updated']; });
  nr_json(['ok' => true, 'projects' => $list, 'ready' => nr_key() !== '', 'voices' => NR_VOICES, 'models' => NR_MODELS, 'tones' => NR_TONES, 'used' => $used, 'cap' => nr_cap()]);
}

$b = tt_body();
$op = (string)($b['a'] ?? '');
$pid = preg_replace('/[^a-z0-9-]/', '', strtolower((string)($b['id'] ?? '')));

if ($op === 'save') {
  $title = tt_clean($b['title'] ?? '', 90);
  if ($title === '') nr_json(['error' => 'Give it a name.'], 400);
  if ($pid === '') { $base = trim(preg_replace('~[^a-z0-9]+~', '-', strtolower($title)), '-') ?: 'narration'; $pid = substr($base, 0, 40); $n = 2; while (nr_get($pid)) $pid = substr($base, 0, 36) . '-' . $n++; }
  $voice = isset(NR_VOICES[$b['voice'] ?? '']) ? $b['voice'] : 'onyx';
  $model = isset(NR_MODELS[$b['model'] ?? '']) ? $b['model'] : 'gpt-4o-mini-tts';
  $speed = max(0.7, min(1.3, round((float)($b['speed'] ?? 1), 2)));
  $tone = isset(NR_TONES[$b['tone_key'] ?? '']) ? NR_TONES[$b['tone_key']] : tt_clean($b['tone'] ?? '', 400);
  $old = nr_get($pid);
  $items = [];
  foreach ((array)($b['items'] ?? []) as $i => $it) {
    $it = (array)$it;
    $text = trim(strip_tags((string)($it['text'] ?? '')));
    if ($text === '') continue;
    $k = preg_replace('/[^A-Za-z0-9_-]/', '', (string)($it['k'] ?? '')) ?: ('s' . ($i + 1));
    $row = ['k' => $k, 'title' => tt_clean($it['title'] ?? '', 90), 'text' => mb_substr($text, 0, 3800),
      'img' => tt_clean($it['img'] ?? '', 200), 'hash' => ''];
    $row['hash'] = nr_hash($row['text'], $voice, $model, (string)$speed);
    if (!is_file(nr_dir() . '/' . $row['hash'] . '.mp3')) $row['hash'] = '';
    $items[] = $row;
    if (count($items) >= 120) break;
  }
  $P = ['id' => $pid, 'title' => $title, 'sub' => tt_clean($b['sub'] ?? '', 160), 'voice' => $voice, 'model' => $model,
    'speed' => $speed, 'tone' => $tone, 'tone_key' => (string)($b['tone_key'] ?? ''), 'items' => $items,
    'live' => !empty($b['live']), 'created' => (int)($old['created'] ?? time()), 'updated' => time()];
  tt_update('narrations.json', function ($d) use ($pid, $P) { $d['projects'][$pid] = $P; return ['data' => $d]; });
  nr_json(['ok' => true, 'id' => $pid, 'url' => tt_site() . '/narrate/?p=' . rawurlencode($pid), 'project' => $P]);
}

if ($op === 'make' || $op === 'remake') {
  $P = nr_get($pid);
  if (!$P) nr_json(['error' => 'Save it first.'], 404);
  $only = $b['only'];
  $only = is_array($only) ? array_map('intval', $only) : null;
  $made = 0; $skipped = 0; $err = '';
  foreach (($P['items'] ?? []) as $i => $it) {
    if ($only !== null && !in_array($i, $only, true)) continue;
    if ($op === 'make' && !empty($it['hash'])) { $skipped++; continue; }
    [$h, $e] = nr_speak((string)$it['text'], (string)$P['voice'], (string)$P['model'], (string)$P['speed'], (string)$P['tone']);
    if ($e !== '') { $err = $e; break; }
    $P['items'][$i]['hash'] = $h; $made++;
    if ($made >= 8) break;   // keep each request short; the panel calls again until it is done
  }
  $P['updated'] = time();
  tt_update('narrations.json', function ($d) use ($pid, $P) { $d['projects'][$pid] = $P; return ['data' => $d]; });
  $left = 0; foreach ($P['items'] as $it) if (empty($it['hash'])) $left++;
  [, , , $used] = nr_use_get();
  nr_json(['ok' => $err === '', 'error' => $err ?: null, 'made' => $made, 'skipped' => $skipped, 'left' => $left,
    'used' => $used, 'cap' => nr_cap(), 'project' => $P]);
}

if ($op === 'delete') {
  if (!nr_get($pid)) nr_json(['error' => 'Not found.'], 404);
  tt_update('narrations.json', function ($d) use ($pid) { unset($d['projects'][$pid]); return ['data' => $d]; });
  nr_json(['ok' => true]);   // the mp3 files stay: other projects may share the same lines
}
nr_json(['error' => 'Unknown action.'], 400);
F79B09340;
$NEW['desk/narrator.js'] = <<<'F2FC66F8C'
/* 3G's Command Center: THE NARRATOR (TTNAR).
   One narration engine for everything. Paste a script, pick a voice, make the audio,
   and share a link that plays it with the slides. Backend: ../api/narrator.php */
(function(){
var TABS = {narr:'The Narrator'};
var S = {list:null, cur:null, msg:'', busy:false, meta:null, view:'list'};
var DECK = [
{"k":"cover","title":"The Outreach Machine","img":"/narrate/slides/cover.jpg","text":"This is the Outreach Machine. One call list, one set of scripts, one scoreboard, pointed at whichever business you pick. It was built on October thirty-first, twenty twenty-six, and from here to the end of the year it is how we go and get customers."},
{"k":"problem","title":"Posting was never the problem","img":"/narrate/slides/problem.jpg","text":"Posting was never the problem. Ads and graphics are conversion assets. They work on people who already found you. What we did not have was a way to go and get a customer on purpose. Forty Orlando churches sat in a spreadsheet nobody opened. Now, you open the tab, and the next call is already at the top."},
{"k":"one-machine","title":"One machine, four businesses","img":"/narrate/slides/one-machine.jpg","text":"One machine runs four businesses. G P T S airport transfers, where we hold a flat rate for a property's guests. Orlando group orders, three shirt designs free in twenty-four hours. G G F G fundraising, where the group keeps five dollars a shirt and puts up nothing. And three G's A I Web Solutions, a free written website audit. Each one carries its own goal."},
{"k":"switcher","title":"Tap the name, everything re-aims","img":"/narrate/slides/switcher.jpg","text":"You tap the name at the top, and everything re-aims. Different leads. Different scripts. Different prices. Different deadlines. Different goal. The number beside each name is how many leads that business has waiting on you."},
{"k":"scoreboard","title":"The number, not the feeling","img":"/narrate/slides/scoreboard.jpg","text":"Every business has one number that tells you whether it worked. Underneath it: calls made, how many got something sent, who is interested, who has been quoted, and how many are still untouched. If the top number is not moving, nothing else on the screen matters."},
{"k":"calllist","title":"Call these now","img":"/narrate/slides/calllist.jpg","text":"Call these now. The list sorts itself. Interested first, then anyone waiting on a quote, then everyone due a follow-up. The green button dials. The last note is right there, so you remember who you spoke to before they even pick up. Ten calls a day is the whole job."},
{"k":"outcomes","title":"One tap after every call","img":"/narrate/slides/outcomes.jpg","text":"After every call, you tap what happened. You never pick a date. No answer sets you back in two days. Call back, one day. Interested, one day. Sent it, three days. Not now, three weeks. Nothing falls through, and nothing has to be remembered. That is the part that makes follow-up actually happen."},
{"k":"script","title":"The words are already written","img":"/narrate/slides/script.jpg","text":"The words are already written. Their name, their business, your price, all filled in before you open it. And the right one is flagged for you. Never called them? The phone script. Interested? The email. Already sent it? The day-three follow-up. Copy, paste, send, then tap what happened."},
{"k":"prices","title":"It cannot quote you into a loss","img":"/narrate/slides/prices.jpg","text":"It cannot quote you into a loss. Margins are worked out from your real cost table every single time the page loads. Blank cost, Stripe, the seven percent tax we absorb, and one-box postage. Crewneck and hoodie prices are solved backwards to hold the same share. Try to build a page under thirty-five percent, and it refuses, and tells you which tier to pick instead."},
{"k":"rates","title":"Every business carries its own card","img":"/narrate/slides/rates.jpg","text":"Every business carries its own card. Switch to G P T S and the ladder becomes the rate card. Switch to A I Web Solutions and it becomes the five packages. Every price came off your own live pages. None were invented. And underneath each card sit the rules you do not break."},
{"k":"inbound","title":"They can come to you too","img":"/narrate/slides/inbound.jpg","text":"They can come to you, too. Four free-offer pages are live, one per business. A flat rate for your guests. Three shirt designs, free. A fundraiser that costs the group nothing. A free website audit. Every form lands in that business's call list and emails you the moment it is sent. The flyers carry a Q R code straight to the page."},
{"k":"editable","title":"Every word is yours to change","img":"/narrate/slides/editable.jpg","text":"Every word is yours to change. The businesses are data, not code. Open Edit this business and change the name, the brand, the phone, the offer line, who you call, the rate card, the rules, the dates, and every script, word for word. Start a brand new business from scratch, or put any one back the way it shipped. A fifth business takes minutes, not a rebuild."},
{"k":"nextbuild","title":"What we build next","img":"/narrate/slides/nextbuild.jpg","text":"Here is what we build next, and what it replaces. A Lead Finder instead of Apollo. Sequences instead of Close and HubSpot. Send from the tool instead of Lemlist. Source tracking instead of CallRail. A money forecast instead of Pipedrive. That stack runs four hundred to nine hundred dollars a month. We build it once, and we own it."},
{"k":"firstmove","title":"Ten calls. Today.","img":"/narrate/slides/firstmove.jpg","text":"The single next move is ten calls today. Open the Outreach Machine. Work Call these now from the top down, and tap what happened after every single one. The machine does not make the call. It makes sure the right call is always on top, the words are ready, and nobody gets forgotten. Kings don't quit."}
];
function $(i){ return document.getElementById(i); }
function e(s){ return String(s==null?'':s).replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
function q(s){ return String(s==null?'':s).replace(/\\/g,'\\\\').replace(/'/g,"\\'"); }
function K(){ try { return sessionStorage.getItem('ttDesk') || ''; } catch(x){ return ''; } }
function get(p){ return fetch('../api/narrator.php' + p, {headers:{'X-TT-Key':K()}, cache:'no-store'}).then(function(r){ return r.json(); }); }
function post(b){ return fetch('../api/narrator.php', {method:'POST', headers:{'Content-Type':'application/json','X-TT-Key':K()}, body:JSON.stringify(b)}).then(function(r){ return r.json(); }); }
function load(){ return get('?a=list').then(function(d){ S.list = d.projects || []; S.meta = d; draw(); }); }
function copy(t, btn){ var done=function(){ var o=btn.getAttribute('data-l')||btn.textContent; btn.setAttribute('data-l',o); btn.textContent='Copied ✓'; setTimeout(function(){btn.textContent=o;},1500); };
  if (navigator.clipboard) navigator.clipboard.writeText(t).then(done, function(){ window.prompt('Copy this:', t); }); else window.prompt('Copy this:', t); }

function blank(){ return {id:'', title:'', sub:'', voice:'onyx', model:'gpt-4o-mini-tts', speed:1, tone_key:'authority', tone:'', live:true, items:[{k:'s1',title:'',text:'',img:'',hash:''}]}; }
function meter(){
  var m = S.meta || {}; if (!m.cap) return '';
  var pct = Math.min(100, Math.round((m.used||0)/m.cap*100));
  return '<div class="nr-meter"><div class="nr-bar"><i style="width:'+pct+'%"></i></div><span>'+(m.used||0).toLocaleString()+' of '+(m.cap||0).toLocaleString()+' characters used this month</span></div>';
}
function vList(){
  var h = '<h2 class="nr-h">🎙 The Narrator</h2><p class="nr-mute">One voice engine for everything: decks, landing pages, ads, walkthroughs. Paste a script, pick a voice, make the audio, and send one link that plays it.</p>' + meter();
  if (S.meta && !S.meta.ready) h += '<div class="nr-err">The voice engine is not switched on for this server yet. Add the key in api/services-config.php and it works everywhere.</div>';
  h += '<div class="nr-acts"><button class="nr-b gold" onclick="TTNAR.make()">➕ New narration</button>' +
       '<button class="nr-b" onclick="TTNAR.fromDeck()">🎯 Narrate the Outreach Machine deck</button>' +
       '<button class="nr-b" onclick="TTNAR.refresh()">↻ Refresh</button></div>';
  if (S.msg) h += '<div class="nr-msg">'+e(S.msg)+'</div>';
  var L = S.list || [];
  if (!L.length) return h + '<div class="nr-empty">Nothing narrated yet. Tap <b>Narrate the Outreach Machine deck</b> to hear what it sounds like.</div>';
  return h + L.map(function(p){
    return '<div class="nr-card"><div class="nr-head"><div><b class="nr-t">'+e(p.title)+'</b><div class="nr-sub">'+p.done+' of '+p.items+' lines ready · voice '+e(p.voice)+(p.live?'':' · not shared yet')+'</div></div>'+
      (p.done===p.items&&p.items?'<em class="nr-ok">Ready</em>':'<em class="nr-wait">'+(p.items-p.done)+' to go</em>')+'</div>'+
      '<div class="nr-acts"><button class="nr-b" onclick="TTNAR.open(\''+q(p.id)+'\')">Open</button>'+
      '<a class="nr-b" href="'+e(p.url)+'" target="_blank" rel="noopener">▶ Play it</a>'+
      '<button class="nr-b sm" onclick="TTNAR.copyText(this,\''+q(p.url)+'\')">Copy the link</button></div></div>';
  }).join('');
}
function vEdit(){
  var P = S.cur, m = S.meta || {};
  var done = P.items.filter(function(x){ return x.hash; }).length;
  var h = '<div class="nr-acts"><button class="nr-b" onclick="TTNAR.back()">← All narrations</button></div>';
  h += '<h2 class="nr-h">'+e(P.title || 'New narration')+'</h2>' + meter();
  if (S.msg) h += '<div class="nr-msg">'+e(S.msg)+'</div>';
  h += '<div class="nr-card"><b class="nr-lb">The basics</b><div class="nr-form">' +
    '<label>Name<input value="'+e(P.title)+'" oninput="TTNAR.set(\'title\',this.value)" placeholder="The Outreach Machine"></label>' +
    '<label>Subtitle<input value="'+e(P.sub)+'" oninput="TTNAR.set(\'sub\',this.value)" placeholder="Narrated walkthrough"></label>' +
    '<label>Voice<select onchange="TTNAR.set(\'voice\',this.value)">' + Object.keys(m.voices||{}).map(function(k){ return '<option value="'+e(k)+'"'+(P.voice===k?' selected':'')+'>'+e(m.voices[k])+'</option>'; }).join('') + '</select></label>' +
    '<label>How it should sound<select onchange="TTNAR.set(\'tone_key\',this.value)">' + Object.keys(m.tones||{}).map(function(k){ return '<option value="'+e(k)+'"'+(P.tone_key===k?' selected':'')+'>'+e(k.charAt(0).toUpperCase()+k.slice(1))+'</option>'; }).join('') + '</select></label>' +
