     '<button id="play">&#9654; Play</button>'+
     '<button id="next">Next &#8594;</button>'+
     '<div id="dots"></div>'+
     '<button class="chip on" id="autob">Auto-advance</button>'+
   '</div><div id="cap"></div></div>';
