function speak(){
  var it=S.d.items[S.i];
  S.playing=true; $('play').innerHTML='&#10073;&#10073; Pause';
  if(it.audio){
    var au=new Audio(it.audio); au._tt=1; S.au=au;
    au.onended=ended;
