   .then(function(d){
     if(d.error||!d.items||!d.items.length){$('app').innerHTML='<div id="msg">'+e(d.error||'Nothing to play yet.')+'</div>';return}
     d.items=d.items.map(function(x){ if(x.audio)x.audio='../'+x.audio; return x; });
