foreach (['api/narrator.php'] as $pf) { $o = []; $rc = 0; @exec('php -l ' . escapeshellarg($root . '/' . $pf) . ' 2>&1', $o, $rc); $t = trim(implode(' ', $o)); if ($rc !== 0 && $t !== '') { $err = true; $lint[] = "ERR $pf: $t"; } else $lint[] = "ok  $pf syntax " . ($t ?: '(linter unavailable, skipped)'); }
$out .= implode("\n", $lint) . "\n";
if ($err) {
  foreach ($files as $f => $c) if (is_file($f . $tag)) copy($f . $tag, $f);
  foreach ($wrote as $f) { if (is_file($f . $tag)) copy($f . $tag, $f); else @unlink($f); }
  $out .= "ROLLED BACK because of a syntax error.\n";
} else { @unlink(__FILE__); $out .= "\nDONE. The Narrator sits next to the Outreach Machine in the Home menu.\n"; }
echo $out;
